B = (10,0,0);
C = (0,10,0);
D = (0,0,10);
a = 0.471548;
b = 0.571548;
c = 0.671548;
d = 5.28452;
X = (-d/a,0,0);
Y = (0,-d/b,0);
Z = (0,0,-d/c);
P = projectionofpointontoplane(B, X, Y, Z);
Q = projectionofpointontoplane(C, X, Y, Z);
R = projectionofpointontoplane(D, X, Y, Z);
