int i, j;

for (i = 0; i <= 8; ++i) {
  draw((i,0)--(i,8));
  draw((0,i)--(8,i));
}

for (i = 0; i <= 7; ++i) {
for (j = 0; j <= 7; ++j) {
  label("$\frac{1}{" + string(i + 8 - j) + "}$", (i + 0.5, j + 0.5));
}}
