draw(G--D--E--F--cycle);
draw(G--O);
draw(F--C--O--A--D);
draw(A--B--C, dashed);
draw(B--E, dashed);
draw(O--D, dashed);
draw(O--F, dashed);
draw(O--X, Arrow);
draw(O--Y, Arrow);
draw(O--Z, Arrow);

label("$2$", A, SE);
label("$2$", C, W);
label("$2$", G, SW);
label("$O$", O, S);
